"""Form Five History Term One. Original practice sources are labelled invented."""
import json
import re
import sys
from pathlib import Path
from itertools import combinations
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import lessonlib as L
import banks_en as B
L.use_class('form-5','Form 5')
OUT=L.ROOT/'history'
PATH=[]
TIMELINES={}

def F(term, meaning, case, error, why):
    return dict(term=term, meaning=meaning, case=case, error=error, why=why)

def sentence(text):
    return text[:1].upper()+text[1:]

def qa(n, key, level, items, sources):
    return B.QA(f'y5-{n}-{key}', level, '{X.q}', items, sources)

def unit(n, title, goal, back, onward, overview, detail, method, facts, sources, prereq=()):
    assert len(facts) >= 4
    banks = [[], [], []]
    for i, f in enumerate(facts):
        others = [x for j, x in enumerate(facts) if i != j][:3]
        banks[0].append(dict(q='Which term or event fits this description: '+f['meaning']+'?', r=f['term'],
          w=[x['term'] for x in others], e=[x['term']+' concerns '+x['meaning']+'. Compare that with the description asked for.' for x in others], y=f['why']))
        banks[1].append(dict(q=f['case']+'\nWhich feature does this example illustrate?', r=f['term'],
          w=[x['term'] for x in others], e=['That identifies '+x['meaning']+'. The example instead concerns '+f['meaning']+'.' for x in others], y=f['why']))
        banks[2].append(dict(q='Invented classroom source for analysis, not an archive quotation: '+f['case']+'\nWhich claim does this text support? Treat it as a practice text; real historical proof requires authentic evidence.',
          r=sentence(f['meaning'])+'.', w=[sentence(x['meaning'])+'.' for x in others],
          e=['That claim concerns '+x['term']+'. This text instead gives evidence about '+f['term']+'; do not add the other claim.' for x in others],
          y='The words of the practice text support '+f['meaning']+'. '+f['why']))
    q0=qa(n,'identify',1,banks[0],sources)
    q1=qa(n,'case',1,banks[1],sources)
    q2=qa(n,'source',2,banks[2],sources)
    q3=B.MT(f'y5-{n}-connect',2,'Match each historical feature to the evidence or example that illustrates it.',[(f['term'],f['case']) for f in facts],sources,pick=3)
    if n in TIMELINES:
        bank=[dict(zip(['a','b','c'],events)) for events in combinations(TIMELINES[n],3)]
        q3=L.order(f'y5-{n}-sequence',2,'Put these dated events in chronological order, earliest first. Then use their sequence to distinguish an earlier condition from a later response.',
          ['{X.a}','{X.b}','{X.c}'],vars={'X':{'pick':bank}},sources=sources,review='authored')
    q4=B.SP(f'y5-{n}-assess',3,'Find the claim that misrepresents the history or the evidence.',
      [f['term']+': '+f['meaning']+'.' for f in facts],[(f['error'],f['why']) for f in facts],sources)
    for statement,f in zip(q4['pool']['right'],facts):
        statement['explain']='This is an accurate distinction: '+f['why']+' Look for a claim that reverses the event, relationship or limit.'
    note=re.sub(r'\{(\d+)\}',r'\1',overview)
    L.lesson('history','history',n,(f'y5-{n}',title),prereq,note,
      L.worked({},'Analyse this invented classroom source, not an archive quotation: '+facts[0]['case'],
        ['Identify the action, actor and setting stated in the text.',sentence(facts[0]['meaning'])+'.',facts[0]['why'],'This practice text helps test reasoning; authenticate and compare real sources before claiming historical proof.'],facts[0]['term']),
      [L.card(f'y5-{n}-c1','Distinguish the historical features before explaining their relationship.',[f['term']+': '+f['meaning']+'.' for f in facts],q0['id']),
       L.card(f'y5-{n}-c2','Connect a specific action or event to the historical feature it illustrates.',[f['case'] for f in facts],q1['id']),
       L.card(f'y5-{n}-c3','Check a claim against the sequence, setting and limits of the evidence.',[f['error']+' Correction: '+f['why'] for f in facts],q4['id'])],
      [q0,q1,q2,q3,q4],learn=L.learn([
       ('Your goal and connections','By the end, you should be able to '+goal+'. Builds on: '+back+'. Leads to: '+onward+'.'),
       ('Explain the history',overview),('Follow the evidence and examples',detail),('Reason and check',method)],
       key_words=[(f['term'],f['meaning']) for f in facts],
       mistake=(facts[0]['error'],facts[0]['term']+': '+facts[0]['meaning']+'.',facts[0]['why'])))
    PATH.append((n,title,goal,back,onward))

TIMELINES.update({
 1:['Gold Coast election success for CPP in {1951}','Nkrumah becomes prime minister in {1952}','Further internal self-government in {1954}','Ghana becomes independent in March {1957}'],
 2:['Federal constitutional arrangements develop in {1954}','Constitutional conference in {1958}','Federal election in {1959}','Nigeria becomes independent in October {1960}'],
 3:['Brazzaville Conference in {1944}','French Union established in {1946}','Loi-cadre reforms in {1956}','Guinea chooses independence in {1958}'],
 4:['Congo becomes independent on {30} June {1960}','Army mutiny begins in early July {1960}','Katanga announces secession on {11} July {1960}','Security Council establishes ONUC on {14} July {1960}'],
 6:['Guinea-Bissau declares independence in {1973}','Portugal’s April revolution in {1974}','Portugal recognises Guinea-Bissau in September {1974}','Mozambique becomes independent in June {1975}'],
 11:['Expansion of the US economy during the {1920}s','US stock-market crash in October {1929}','US banking panics during {1930}–{1931}','Roosevelt’s banking holiday in March {1933}'],
 15:['Cameroon admitted to the UN in September {1960}','Cameroon among OAU founders in May {1963}','European Union established in {1993}','African Union launched in {2002}']
})

def h(n,title,goal,back,onward,overview,detail,facts,key,prereq=()):
    unit(n,title,goal,back,onward,overview,detail,
      'Identify actor, action, place and period before explaining a relationship. Use the practice text only for the claim it supports. Distinguish a cause, an event and an outcome; compare authentic sources before treating an interpretation as established. A sequence alone does not prove that every later outcome was inevitable.',facts,[key],prereq)

h(1,'Decolonisation case study: the Gold Coast becomes Ghana','connect nationalist organisation, constitutional change and independence without erasing African agency',
 'Form Four nationalism and postwar international change','comparison with Nigeria and French West Africa',
 'The Gold Coast’s route to independence combined African political mobilisation, elections and negotiation under changing British rule. Kwame Nkrumah’s Convention People’s Party pressed for self-government and gained electoral strength. Constitutional changes expanded African responsibility before sovereignty was transferred. Internal self-government did not yet remove every power reserved to the colonial governor. Ghana became independent on {6} March {1957}. This was a political process with disagreements, not a gift requiring no African action or a guarantee of all future outcomes.',
 'The CPP’s electoral success in {1951} contributed to Nkrumah’s release from imprisonment and entry into government. He became prime minister in {1952}; the {1954} constitution widened internal self-government while some powers remained reserved. Independence in {1957} changed sovereign status. An official British debate provides evidence of constitutional proposals and its speakers’ viewpoints; it does not represent every Ghanaian voice.',[
 F('nationalist mobilisation','African organisation and pressure for self-government','The CPP campaigned and won electoral support for a self-government programme.','Ghanaian independence occurred without African political organisation.','African parties and mobilisation were central to the process.'),
 F('constitutional advance','an expansion of internal governing responsibility before sovereignty','The {1954} constitution increased internal self-government while reserved powers remained.','Internal self-government meant every colonial power had already disappeared.','Reserved authority distinguished autonomy from full sovereignty.'),
 F('independence','the transfer to sovereign status in the Ghana case','Ghana became independent on {6} March {1957}.','Ghana became independent only after Nigeria in {1960}.','Ghana’s independence preceded Nigeria’s.'),
 F('source perspective','a speaker’s institutional position shaping what a source can establish','A British parliamentary debate records proposals and disagreement, not all Ghanaian opinion.','A speech by one official proves unanimous popular consent.','Other voices and evidence are needed to assess wider opinion.')],'decolonisation')

h(2,'Decolonisation case study: Nigeria’s negotiated transition','explain how federal arrangements and political negotiation shaped Nigeria’s independence',
 'Ghana’s constitutional route and the distinction between autonomy and sovereignty','French West Africa and comparison of varied transitions',
 'Nigeria’s transition involved nationalist parties, regional interests, constitutional conferences and federal arrangements under British rule. A federal framework allocated authority between central and regional institutions; it did not mean that all political interests became identical. The federal election of {1959} preceded independence on {1} October {1960}. Abubakar Tafawa Balewa headed the federal government at independence. Later instability should not be read backward as proof that constitutional negotiation had no meaning or that conflict was inevitable.',
 'Federal arrangements developed during the {1950}s. The {1958} constitutional conference set out a path toward independence, followed by the {1959} election and parliamentary steps. Independence changed Nigeria’s status while questions of regional balance and political inclusion remained. Compare the mechanism with Ghana without assuming identical parties, dates or constitutional structures.',[
 F('federal arrangement','division of governing responsibilities between central and regional institutions','Negotiations addressed a federal centre and regional governments.','A federation means regions have no institutions or powers.','Federal arrangements allocate authority across levels.'),
 F('constitutional negotiation','political bargaining about rules and the transition to sovereignty','The {1958} conference formed part of the independence process.','All constitutional conferences occurred after independence only.','This conference preceded the {1960} transition.'),
 F('independence sequence','the election and political steps preceding sovereign status','The federal election in {1959} preceded independence on {1} October {1960}.','Nigeria’s {1960} independence preceded Ghana’s {1957} independence.','The dated sequence gives the opposite order.'),
 F('continuing political questions','issues that a sovereign transition did not automatically settle','Regional balance remained important after the transfer of power.','Independence guaranteed the permanent disappearance of political disagreement.','A change of status does not resolve every institutional issue.')],'decolonisation',[1])

h(3,'French West Africa: reform, Community and Guinea’s choice','order constitutional changes and explain Guinea’s distinctive referendum choice',
 'different British transitions and postwar nationalism','the Congo and Portuguese comparisons',
 'French West African decolonisation developed through postwar reform and African political pressure. The Brazzaville Conference in {1944} considered reforms within empire, not immediate independence. The French Union of {1946} changed the framework but preserved colonial inequalities. The loi-cadre of {1956} expanded territorial political responsibility. In the {1958} referendum, Guinea rejected the proposed French Community and declared independence in October under Sékou Touré. Other territories followed different routes, with many attaining independence in {1960}. Reform and independence are distinct stages.',
 'Sékou Touré and the Guinean Democratic Party favoured the No vote in {1958}. Guinea’s independence was proclaimed on {2} October. The break brought political and economic difficulties in relations with France, not an automatic end to every form of dependency. Contemporary official accounts must be compared with African perspectives; their language about reform can reflect the former colonial state’s viewpoint.',[
 F('Brazzaville reform setting','wartime discussion of reform within French imperial rule','The {1944} conference did not grant immediate sovereign independence to every colony.','Brazzaville made every West African territory independent in {1944}.','The conference’s reform framework remained imperial.'),
 F('French Union','the postwar framework established in {1946} before full sovereignty','Territorial political representation expanded without simply ending colonial rule.','The French Union was identical to independent nationhood for every territory.','Formal reform did not remove every inequality or reserved power.'),
 F('loi-cadre','the {1956} reform expanding territorial governing responsibility','Local councils and territorial political authority gained a wider role.','The loi-cadre was adopted only after all territories were independent.','The reform preceded the principal independence transitions.'),
 F('Guinea’s No vote','rejection of the proposed Community followed by independence in {1958}','Guinea chose No and proclaimed independence on {2} October {1958}.','Guinea followed the same Yes vote as every other territory.','Its referendum choice was distinctive.')],'decolonisation',[1,2])

h(4,'Belgian Congo: independence and the outbreak of crisis','connect a rapid transfer, army mutiny, secession and foreign intervention without reducing the crisis to one cause',
 'varied colonial transitions and limits of constitutional transfer','the Congo crisis’s effects and post-independence instability',
 'The Belgian Congo became independent on {30} June {1960}. Colonial inequalities, weak preparation for African control of key institutions and disputes over authority made the transition difficult. An army mutiny, Belgian military intervention and secessionist movements rapidly deepened the crisis. Katanga declared secession in July. Congolese rivalries interacted with foreign political and economic interests in a Cold War setting. No single label explains every cause, and the crisis is not proof that Africans were inherently unable to govern.',
 'The army mutiny began in early July {1960}; Katanga’s secession under Moïse Tshombe was announced on {11} July. The Congolese government requested UN assistance, and the Security Council established ONUC on {14} July. These connected developments should be distinguished from Congo’s legal independence and from the operation’s later outcomes.',[
 F('independence transfer','the Congo’s move from Belgian colony to sovereignty in June {1960}','The Republic of the Congo became independent on {30} June {1960}.','Legal independence guaranteed that every state institution was already stable.','Sovereignty and institutional capacity are different questions.'),
 F('army mutiny','a breakdown of military discipline during the early crisis','An army mutiny began soon after independence in July {1960}.','The mutiny was simply a peaceful constitutional election.','It involved a breakdown within the armed forces.'),
 F('Katanga secession','the attempt to separate a province from the new state','Katanga declared secession under Tshombe in July {1960}.','Secession meant only changing a minister within the same central government.','It challenged the state’s territorial unity.'),
 F('international intervention','outside military and diplomatic involvement in the crisis','Belgian intervention and requested UN assistance internationalised the emergency.','No foreign actor was involved in the Congo crisis.','Outside involvement is explicitly part of its history.')],'congo',[3])

h(5,'Belgian Congo: consequences and the limits of intervention','explain political and human effects while distinguishing ONUC’s task from a complete solution',
 'independence, mutiny and secession in the Congo crisis','Portuguese transitions and comparative instability',
 'The Congo crisis disrupted administration and economic activity, displaced people and intensified conflict over national leadership and territorial unity. Prime Minister Patrice Lumumba was killed in {1961}. ONUC operated from July {1960} to June {1964}, with a mandate that developed during the crisis. Katanga was reintegrated, but political instability did not simply disappear. Mobutu seized power in {1965}. Distinguish an operation’s specific achievements from a claim that it settled every later conflict.',
 'UN accounts describe efforts concerning territorial integrity, foreign military elements and the prevention of wider civil war. Human suffering and political rivalry outlasted a single resolution. Later centralisation under Mobutu was not the same event as independence in {1960}. This lesson concerns the early post-independence Congo crisis, not every later war in today’s Democratic Republic of the Congo.',[
 F('human and economic disruption','damage to daily life, movement and state activity during the crisis','Conflict displaced people and interrupted administration and economic activity.','Civil conflict affects only the wording of constitutional documents.','Its consequences extend to people and livelihoods.'),
 F('leadership crisis','violent conflict over the new state’s political leadership','Lumumba was killed in {1961} during the wider crisis.','Lumumba’s death occurred before the Congo gained independence.','The killing followed independence in {1960}.'),
 F('ONUC’s limited achievement','specific international action without a guarantee of permanent peace','Katanga’s reintegration did not eliminate every later political conflict.','ONUC’s withdrawal proved all future Congolese instability had ended.','A mandate and a period of intervention have limits.'),
 F('later centralisation','the later seizure of state power under Mobutu','Mobutu seized power in {1965}, after the initial independence crisis.','Mobutu’s {1965} seizure and June {1960} independence were the same event.','They were distinct events in different years.')],'congo',[4])

h(6,'Portuguese Africa: delayed decolonisation and varied transitions','identify the territories and connect liberation struggles with the change of regime in Portugal',
 'British, French and Belgian transitions','post-independence instability and comparative explanations',
 'Portugal retained its African empire while many other colonies became independent. Its authoritarian government defended continued control, and liberation movements fought protracted wars in Angola, Mozambique and Guinea-Bissau. Angola, Mozambique, Guinea-Bissau, Cape Verde and São Tomé and Príncipe followed distinct routes. Portugal’s April revolution in {1974} changed the metropolitan political framework and opened negotiations. Guinea-Bissau declared independence in {1973} and gained Portuguese recognition in {1974}; Mozambique, Cape Verde, São Tomé and Príncipe and Angola became independent in {1975}. Declaration and recognition must be distinguished.',
 'Examples of movements include FRELIMO in Mozambique, PAIGC in Guinea-Bissau/Cape Verde, and rival movements including MPLA, FNLA and UNITA in Angola. The {1974} revolution did not erase earlier African resistance or guarantee peaceful transitions everywhere. Angola’s continuing conflict illustrates why independence and lasting peace are separate questions.',[
 F('continued colonial rule','Portugal’s prolonged defence of its African empire','The authoritarian Portuguese regime resisted independence while wars developed in several territories.','Every Portuguese territory followed Ghana’s peaceful constitutional timetable.','The regimes and routes differed.'),
 F('liberation movements','African organisations pursuing independence through political and armed struggle','FRELIMO organised the independence struggle in Mozambique.','African resistance began only after Portugal had already transferred all power.','Movements and struggles preceded the final transfers.'),
 F('metropolitan turning point','the change in Portugal enabling a new decolonisation policy','The April {1974} revolution opened a different political route to negotiation.','The revolution made earlier African resistance irrelevant.','Metropolitan change interacted with prior struggles and pressure.'),
 F('distinct transition stages','the difference between declaration, recognition and later political outcomes','Guinea-Bissau declared in {1973} and Portugal recognised it in {1974}.','Declaration and Portuguese recognition necessarily occurred in the same year everywhere.','The Guinean sequence shows distinct stages.')],'portuguese',[3,4,5])

h(7,'Political instability in post-independence Africa','explain interacting institutional, economic and external pressures without stereotyping a continent',
 'different colonial transitions and their unresolved issues','military coups and their claimed justifications',
 'African states had diverse post-independence experiences; instability was not a universal or inevitable result of independence. In particular cases, inherited institutional weaknesses, struggles over political inclusion, unequal resource distribution, economic shocks and external interference interacted. Leaders and organised groups also made choices that shaped outcomes. Ethnic identity alone is not a sufficient explanation of conflict. A serious account identifies a mechanism and evidence for a particular place and time rather than treating every country as interchangeable.',
 'An institutional dispute may concern who can exercise authority; an economic pressure may concern revenue or employment; external involvement may supply support to a faction. These can reinforce one another, but one example does not prove the same chain everywhere. Compare the Congo’s specific crisis with another case instead of presenting a single continental story.',[
 F('institutional dispute','conflict over legitimate authority and governing rules in a particular case','Competing leaders contest which institution can exercise state authority.','Every political dispute is explained completely by climate alone.','The stated dispute concerns institutions and authority.'),
 F('political exclusion','restriction of participation or unequal access to power','A group argues that it lacks meaningful access to political decisions.','Participation and exclusion always mean exactly the same arrangement.','They describe different political relationships.'),
 F('economic pressure','material constraints that can intensify political tensions','A fall in export receipts reduces resources available for public commitments.','Economic shocks automatically produce identical coups in every country.','Outcomes depend on institutions, choices and other conditions.'),
 F('external involvement','outside support or pressure affecting a domestic political struggle','Foreign backing strengthens a faction in a Cold War contest.','All post-independence conflicts had no international dimension.','Some specific conflicts involved outside powers.')],'instability',[4,5,6])

h(8,'Military coups: change of ruler and constitutional legitimacy','distinguish an unconstitutional military seizure from an elected transition and assess a justification critically',
 'institutional conflict and interacting causes of instability','later evaluation of political and economic change',
 'A military coup is an unconstitutional seizure of state power involving armed forces. It differs from a change through the established electoral and constitutional process. Plotters may claim to end corruption or disorder, but a justification does not establish that the claim is true or that military government will deliver the promised remedy. Ghana’s overthrow of Nkrumah in {1966} is one historical example. Different coups had different actors, settings and consequences; military rule is not a synonym for every change of government.',
 'Original practice statement, not a historical quotation: An army council announces that it has taken control outside the normal constitutional rules and promises to restore order. The wording supports identifying a coup and a stated justification. It does not prove popular unanimity or a successful future outcome. A return to civilian officeholders also requires examination of institutions before it is called a democratic transition.',[
 F('military coup','an unconstitutional seizure of state power involving armed forces','Ghana’s government under Nkrumah was overthrown by a coup in {1966}.','Every election that replaces a government is a military coup.','An electoral transition follows a different mechanism.'),
 F('claimed justification','the reason coup leaders publicly offer for their action','The invented council promises to restore order.','A promise proves that the stated problem is solved already.','The statement records an intention, not an achieved result.'),
 F('constitutional distinction','comparison of the transfer with established governing rules','The invented statement explicitly bypasses normal constitutional procedures.','Military rank automatically replaces every constitutional requirement.','Rank and constitutional legitimacy are different matters.'),
 F('outcome assessment','evaluation using subsequent evidence rather than the takeover’s claim alone','The promise must be compared with later conduct and institutions.','A new ruler guarantees democratic participation for everyone.','Institutions and actions need separate evidence.')],'instability',[7])

h(9,'European science, technology and uneven change before the First World War','connect selected innovations with medicine, transport and military competition without anachronism',
 'earlier industrialisation and international rivalry','the social and global impact of industrial growth',
 'Between {1870} and {1914}, industrial Europe saw wider use of steel, electricity, chemical production and faster communications. Rail and steam transport expanded from earlier foundations, while motor vehicles and early aviation developed. Germ theory and antiseptic practice changed medicine, though access and public health remained uneven. Expanding armies and naval competition linked technology to military rivalry. These changes had earlier roots and international connections; not every invention originated in Europe or within this period.',
 'A late industrial city could combine electric lighting with poor housing and unequal medical access. New transport could move goods and people faster without eliminating cost or exclusion. British parliamentary discussion in March {1914} compared dreadnought-type fleets, showing how industrial capacity entered naval rivalry. Antibiotics as widely used treatments belong to a later period, not a universal medical reality before {1914}.',[
 F('industrial technology','wider application of steel, electricity and chemical processes','Factories and urban services used new power and industrial techniques.','Electricity and railways had no history before {1870}.','Their roots predated the period of wider adoption.'),
 F('medical change','development of scientific explanations and practices against infection','Germ theory and antiseptic practice influenced treatment and public health.','Modern antibiotics were universally available across Europe before {1914}.','That is an anachronistic claim about a later treatment era.'),
 F('transport development','expanding networks and new transport forms with uneven access','Railways, steamships and emerging motor transport altered connections.','Faster transport eliminated every cost and inequality.','Infrastructure and access remained uneven.'),
 F('military-industrial competition','industrial capacity contributing to arms and naval rivalry','A {1914} parliamentary question compares dreadnought-type fleets.','Industrial military expansion automatically guaranteed peace.','Competition could intensify insecurity rather than remove it.')],'industry',[7,8])

h(10,'Industrialisation: effects in Europe and the wider world','weigh production and connectivity against labour, environmental and colonial inequalities',
 'science, transport and industrial capacity','economic expansion, vulnerability and the Great Depression',
 'Industrialisation expanded production, urban employment and transport connections, but benefits and costs were distributed unequally. Workers could face dangerous conditions, long hours and insecure housing; trade unions and reform campaigns sought change. Industrial growth increased demand for resources and markets, interacting with imperial expansion and unequal colonial economies. Smoke, waste and crowded settlements affected environments and health. Avoid describing either universal prosperity or nothing but decline: identify whose experience, which mechanism and what period are being considered.',
 'A factory’s output could rise while workers organised over conditions. A railway could connect an export-producing area to a port without serving every local need equally. Such examples show why increased total production does not by itself establish equal gains. Environmental damage and reform efforts also belong to the historical explanation.',[
 F('production growth','an expansion of output through industrial organisation and technology','Factory organisation increased the scale of goods produced.','Higher total output proves every person gained equally.','Distribution and working conditions require separate evidence.'),
 F('labour response','workers’ organisation and reform demands concerning industrial conditions','Workers formed unions and campaigned over hours and conditions.','Workers had no agency in responding to industrial change.','Organisation and reform were important responses.'),
 F('unequal global connections','industrial demand and transport linking regions through uneven economic relationships','An export railway could prioritise resource movement to a port.','Every colonial railway was designed equally around all local needs.','The purpose and distribution of benefits must be examined.'),
 F('environmental cost','damage associated with industrial production and urban concentration','Smoke and waste affected industrial settlements.','Industrial growth had no possible effects on surroundings or health.','Pollution and living conditions formed part of its costs.')],'industry',[9])

h(11,'The Great Depression: boom, crash and deepening contraction','distinguish boom vulnerabilities, the stock-market crash and banking amplification',
 'industrial production, markets and unequal gains','manifestations and international consequences of the Depression',
 'The US economy expanded during the {1920}s, but prosperity was uneven and speculative borrowing increased vulnerability. The downturn began in {1929}; the October stock-market crash damaged wealth and confidence. Later banking panics and contracting credit deepened the collapse. Weak demand, deflation and international financial links helped spread difficulties. The crash was important but not a complete single-cause explanation. A financial event, the mechanism amplifying it and the wider depression should be distinguished.',
 'US banking panics developed during {1930}–{1931}; the national banking emergency reached a critical point in March {1933}. A factory’s falling orders, depositors’ withdrawals and reduced credit could reinforce one another. The order matters: later tariff restrictions or policy decisions cannot simply be presented as events that occurred before the {1929} crash.',[
 F('uneven boom','growth accompanied by unequal gains and financial vulnerability','Speculative borrowing increased exposure to a fall in share prices.','Every household benefited equally and no vulnerability existed during the boom.','Growth can coexist with unequal gains and risk.'),
 F('stock-market crash','the sharp fall in US share prices in October {1929}','Selling and falling prices damaged confidence and wealth.','The crash alone explains every feature of a decade-long global depression.','Banking, demand, policy and international mechanisms also mattered.'),
 F('banking amplification','bank failures and credit contraction deepening the downturn','Banking panics disrupted credit and payments after the crash.','All banking panics in this account occurred only before the {1929} crash.','The {1930}–{1931} panics followed it.'),
 F('international transmission','financial and trading links carrying effects across economies','Reduced lending and trade connected the downturn to other countries.','Every economy was isolated from international finance and trade.','Cross-border relationships helped transmit shocks.')],'depression',[10])

h(12,'The Great Depression: manifestations, responses and consequences','explain economic hardship and varied political responses without treating dictatorship as inevitable',
 'boom vulnerabilities, crash and banking contraction','regional cooperation and international economic relationships',
 'The Depression brought severe unemployment, falling output and prices, business failures and hardship. Trade contraction affected exporters, including colonial economies dependent on a narrow range of products. Governments responded differently through relief, public works, financial reform or other policies. Roosevelt’s New Deal began in {1933} in the United States. Political extremism gained opportunities in some settings, but dictatorship was not an inevitable or identical outcome everywhere. Recovery timing varied, and the American chronology should not be imposed on every country.',
 'A fall in export earnings could reduce colonial producers’ incomes even without a local stock exchange. Falling prices could coexist with lower incomes and debt difficulties. Relief and reform were responses, not proof that every policy solved every problem immediately. Compare causes with manifestations and longer-term consequences using a specific country and period.',[
 F('economic manifestation','an observable feature of the downturn such as unemployment or falling output','Factories reduced production and many workers lost jobs.','A depression is defined by every household enjoying rising employment.','The stated manifestations show contraction and hardship.'),
 F('export vulnerability','exposure of an export-dependent economy to falling overseas demand or prices','Lower world demand reduced earnings from a narrow export base.','A country needed its own major share market to be affected.','Trade could transmit hardship through export earnings.'),
 F('policy response','action intended to address hardship or financial instability','The New Deal introduced US relief and reform measures from {1933}.','A policy announcement proves an immediate universal recovery.','Results require evidence and differed across measures and time.'),
 F('political consequence with limits','political changes whose outcome depended on the particular setting','Extremist movements gained opportunities in some affected countries.','Every affected country inevitably became the same kind of dictatorship.','Economic crisis interacted with institutions and political choices.')],'depression',[11])

h(13,'Cameroon in CEMAC: membership, geography and cooperation','identify the regional scope and distinguish economic from monetary integration',
 'international economic links and post-independence institutions','obstacles to regional integration and wider organisations',
 'CEMAC links Cameroon, Central African Republic, Chad, Republic of the Congo, Equatorial Guinea and Gabon. It is not identical to all Central Africa, and the Democratic Republic of the Congo is not a CEMAC member. Its treaty was signed in {1994}, following earlier regional cooperation through UDEAC. Economic integration and monetary cooperation are connected but distinct. Common institutions and rules aim to improve regional links; their existence does not prove that every practical barrier has disappeared.',
 'Cameroon’s coast and transport links can connect inland neighbours with maritime routes. Chad and Central African Republic are landlocked; the other listed members have Atlantic coasts. BEAC provides the common monetary framework. A common currency is different from a completed common market or a guarantee that every road and border procedure works without difficulty.',[
 F('CEMAC membership','the named regional group rather than every Central African state','Cameroon belongs with Chad, CAR, Congo, Gabon and Equatorial Guinea.','DR Congo and Republic of the Congo are interchangeable CEMAC members.','They are different states; the Republic of the Congo is in this membership list.'),
 F('economic integration','cooperation seeking closer markets and economic connections','Regional rules and projects aim to improve movement and economic links.','An economic objective proves that every barrier has already vanished.','Implementation needs separate evidence.'),
 F('monetary cooperation','a shared monetary framework distinct from all market arrangements','The listed states share the BEAC framework.','Common currency and every aspect of a common market are identical.','Monetary and economic integration have distinct components.'),
 F('geographic connection','the importance of coastal and landlocked relationships for regional transport','Cameroon’s routes can connect inland neighbours to the coast.','All CEMAC countries are landlocked.','Several listed states have Atlantic coasts.')],'cemac',[10,12])

h(14,'Cameroon in CEMAC: setbacks and assessing progress','explain an integration obstacle through its mechanism without confusing a treaty with an achieved result',
 'CEMAC’s membership, aims and geographic links','wider multilateral and bilateral cooperation',
 'Regional integration depends on practical implementation as well as agreements. Inadequate transport connections can raise time and cost; administrative difficulties can obstruct movement; insecurity can interrupt routes; uneven resources and priorities can complicate joint projects. These are mechanisms to investigate, not claims that every barrier exists everywhere at every date. A careful assessment compares a stated objective with dated evidence of what changed. Neither an agreement nor one example of difficulty establishes the success or failure of the entire organisation.',
 'Original practice case, not a report of a current border: traders face a long delay because a connecting road is damaged while a regional document promises easier movement. The contrast supports identifying an implementation obstacle. It gives no current customs rule, travel condition or measured regional trade total. Another dated source would be needed to assess progress.',[
 F('infrastructure obstacle','a physical connection problem that can hinder integration','A damaged link delays the movement of goods in the invented case.','Signing an agreement instantly repairs every road.','Physical projects require implementation and maintenance.'),
 F('administrative obstacle','a procedural difficulty that can impede an integration objective','An invented case describes incompatible procedures causing delays.','Every delay proves the countries have no shared institutions.','A practical obstacle can coexist with institutional cooperation.'),
 F('security constraint','insecurity affecting the practical use of regional connections','An invented route is interrupted by insecurity.','A common currency automatically removes every security risk.','Monetary cooperation does not itself settle every security problem.'),
 F('implementation assessment','comparison of stated aims with dated evidence of practical results','A promise of easier movement is compared with actual evidence from the same period.','One isolated success proves every objective fully achieved forever.','Scope, place and period limit the conclusion.')],'cemac',[13])

h(15,'Cameroon’s relations with the UN, AU and EU','distinguish membership, institutional succession and external partnership',
 'regional cooperation and evidence of implementation','Commonwealth, Francophonie and other international relationships',
 'Cameroon was admitted to the United Nations on {20} September {1960}. It was among the founders of the Organisation of African Unity in {1963}; the African Union, launched in {2002}, succeeded the OAU. Cameroon cooperates with the European Union but is not an EU member. These organisations have different scopes and functions. Economic support, political dialogue and cooperation can overlap without becoming the same institutional relationship. A programme’s announced aim should be distinguished from measured results.',
 'The UN admission resolution establishes a membership event, not a statement that every UN activity in Cameroon succeeded. AU records place Cameroon among OAU founders. EU descriptions document partnership in areas such as development, trade and infrastructure. A development project does not transfer Cameroon into EU membership or prove equal benefits for all groups.',[
 F('UN membership','admission to the United Nations in September {1960}','The General Assembly admitted Cameroon on {20} September {1960}.','Cameroon joined the UN only after the AU was launched in {2002}.','The membership event occurred much earlier.'),
 F('OAU to AU','institutional succession from the OAU to the African Union','Cameroon was an OAU founder in {1963}; the AU was launched in {2002}.','OAU and AU were unrelated organisations with no succession.','The AU succeeded the OAU.'),
 F('EU partnership','cooperation with the EU without EU membership','Cameroon and the EU cooperate on development and trade.','Receiving EU cooperation makes Cameroon an EU member state.','Partnership and membership are distinct.'),
 F('programme assessment','evaluation of a cooperation project beyond its stated intention','An infrastructure objective is compared with dated evidence of delivery.','An announcement proves all intended benefits reached every person.','Implementation and distribution require evidence.')],'relations',[13,14])

h(16,'Commonwealth, Francophonie and relations with the Arab world','separate organisational membership from language links, bilateral contacts and interregional cooperation',
 'UN/AU membership and EU partnership','relations with major powers and critical comparison of sources',
 'Cameroon joined the Commonwealth in {1995} and is a member of the Organisation internationale de la Francophonie. These provide frameworks for political dialogue, education and cooperation with different histories. French and English links do not make Cameroon a member of every organisation associated with those languages. Cameroon is not a member of the League of Arab States. Relations with Arab member countries and Africa–Arab interregional frameworks must be distinguished from League membership. A specific programme or visit requires its own dated source.',
 'Commonwealth records date Cameroon’s accession to {1} November {1995}. OIF lists confirm its membership, while historical association and full-participation dates need careful terminology. The Arab League’s member list excludes Cameroon. Cooperation with an Arab state is bilateral unless evidence identifies a role for the League itself; a language, religion or meeting location does not alone establish membership.',[
 F('Commonwealth membership','Cameroon’s accession to the Commonwealth in {1995}','The organisation’s history records Cameroon joining on {1} November {1995}.','Cameroon joined the Commonwealth automatically on independence in {1960}.','The accession was later than independence.'),
 F('Francophonie participation','Cameroon’s membership and cooperation in a French-language institutional framework','OIF membership lists include Cameroon.','French-language use alone proves membership of every international body.','Institutional membership needs specific evidence.'),
 F('Arab League distinction','separation of Arab-world relationships from League membership','Cameroon is not on the League’s member list.','Every African state is automatically a member of the Arab League.','The organisations have different memberships.'),
 F('bilateral versus organisational','the difference between a state-to-state relationship and an organisation’s programme','An agreement with an Arab country does not alone establish a League programme.','A bilateral agreement always proves the League signed it.','The actual parties and institutional role must be checked.')],'relations',[15])

h(17,'Cameroon and major powers: USA, Russia and China','compare diplomatic histories and cooperation claims without assuming permanent alignment or guaranteed benefit',
 'membership, partnership and institutional source limits','later evaluation of Cameroon’s foreign relations',
 'Cameroon has developed relationships with major powers through diplomacy and changing forms of cooperation. The United States established diplomatic relations in {1960}. Relations with the Soviet Union began in {1964}; Cameroon recognised the Russian Federation as its successor in {1992}. Diplomatic relations with the People’s Republic of China were established in {1971}. Distinguish the Soviet historical period from later Russian relations. An agreement or project can express mutual aims without proving that interests coincide on every issue or that every promised benefit is delivered.',
 'A US historical record documents recognition and embassy relations in {1960}. A Cameroonian official dossier distinguishes the Soviet and Russian stages. The {1971} China–Cameroon joint communiqué states principles and cooperation aims; these are positions expressed by its signatories, not proof of every later outcome. Compare economic and socio-political cooperation using dated evidence and the actual terms, rather than calling every loan a gift or every relationship an alliance.',[
 F('US diplomatic relationship','recognition and diplomatic relations established in {1960}','The US consular post became an embassy as relations were established at independence.','Every diplomatic relationship means automatic agreement on every policy.','Diplomacy does not eliminate different interests.'),
 F('Soviet and Russian stages','the distinction between relations begun with the USSR and later succession','Relations began with the USSR in {1964}; successor recognition concerned Russia in {1992}.','The Soviet Union and Russian Federation are identical names for one unchanged historical period.','Political succession and historical context must be distinguished.'),
 F('China relationship','diplomatic relations established through the {1971} joint communiqué','The communiqué expresses sovereignty and cooperation principles.','A communiqué proves every future project has already succeeded.','Stated principles and future outcomes differ.'),
 F('critical cooperation comparison','assessment of dates, terms and outcomes across relationships','A project’s funding terms and results are checked rather than assumed.','Every loan is a gift and every partnership a permanent alliance.','Forms of finance and political relationships differ.')],'relations',[15,16])

OUT.mkdir(parents=True,exist_ok=True)
